package paasio

import (
	"io"
	"sync"
)

// ReadCounter counts the bytes and operations read from an io.Reader.
type ReadCounter interface {
	io.Reader
	// ReadCount returns the total number of bytes and
	// Read calls successfully read.
	ReadCount() (bytes int64, ops int)
}

// WriteCounter counts the bytes and operations written to an io.Writer.
type WriteCounter interface {
	io.Writer
	// WriteCount returns the total number of bytes and
	// Write calls successfully written.
	WriteCount() (bytes int64, ops int)
}

// ReadWriteCounter counts the bytes and operations
// read from and written to an io.ReadWriter.
type ReadWriteCounter interface {
	ReadCounter
	WriteCounter
}

type readCounter struct {
	mu sync.Mutex
	r  io.Reader
	n  int64
	ops int
}

func NewReadCounter(r io.Reader) ReadCounter {
	return &readCounter{r: r}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.r.Read(p)
	rc.mu.Lock()
	rc.n += int64(n)
	rc.ops++
	rc.mu.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.ops
}

